/* Host regression test for the Atari 2600 systems ("atari2600-tia-ntsc", "atari2600-tia-pal"): Thor Tracker's own
 * player (tia/tia_player.c) on Stella 7.0's TIA audio channels (tia/tia_stella.cpp) on the colour-clock timeline
 * (tia/tia_machine.c), playing the hand-built test song tools/audio/tia/tia_song.py (tia_test_song.h, generated by
 * tools/audio/prepare_tia.py), plus small images built here for measurements.
 *
 * Checks: the AUDF edge tables against their formula and their edge semantics (every region, class and k), the
 * chosen divider being the nearest in log frequency for every pitch, the mixing table; image validation (single-byte
 * corruptions of the song rejected with the offending byte, region mismatches, constructed images); register writes
 * and positions identical to the independent Python reference player (tools/audio/tia/tia_ref.py) in each of
 * TIA_REF_TICKS ticks for the song, a re-laid-out copy, the edited and tempo songs and the PAL variant, and its reset
 * batch; channel levels after every phase 1 and the channels' counter states identical to the reference chip (NTSC
 * and PAL); frames per tick; deterministic, non-silent output; pitch (A-4 on AUDC C measured against A / (6 x 12),
 * a div-2 and a div-31 note against A / (P (AUDF + 1)), raw and constant waveforms); seeks landing on exact rows with
 * the reference's writes afterwards and bit-identical sound and channel states, the order fallback and unreachable
 * rows; mute (channel states unchanged, silence, continuity on unmute); live edits (the same image, a re-laid image,
 * the reference's live trace, tempo, a cut song, slot identity with byte-identical instruments, an undefined slot
 * stopping its note, an image of the other region ignored); audition and release (release point, none, before any
 * tick, the 10 s cap, argument limits); both ops tables as the hosts drive them; optionally the app's exported
 * tia-*.tiaimg samples (argv[2] or $THOR_SAMPLES). Numeric thresholds marked "assumption" are judgement, not spec.
 *
 * Build and run (no Android needed): tools/audio/run_native_host_test.sh [evidence-dir]
 * Writes <dir>/tia_song.wav and tia_song_pal.wav (48 kHz stereo, ~30 s), tia_tone.wav (NTSC A-4 audition on AUDC C,
 * 120 ticks), tia_tone_pal.wav (PAL, 100 ticks), tia_trace.txt and tia_song.bin (the image), the inputs of
 * tools/audio/tia/tia_reference_check.py. tia_trace.txt: one line per player tick of the test song (the reset batch
 * excluded), printf "%d %d %d:" with the position (order, row, tick) before the tick, then " %02X=%02X" (register,
 * value) per write of the tick's batch in order, then a newline; TIA_REF_TICKS lines. */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include "blip_buf.h"
#include "chip_engine.h"
#include "tia_machine.h"
#include "tia_test_song.h"

static int failures = 0;
static int checks = 0;
#define EXPECT(cond, ...)                                              \
    do {                                                               \
        ++checks;                                                      \
        if (!(cond)) {                                                 \
            ++failures;                                                \
            printf("  FAIL %s:%d: ", __FILE__, __LINE__);              \
            printf(__VA_ARGS__);                                       \
            printf("\n");                                              \
        }                                                              \
    } while (0)

#define RATE 48000
#define A4 57
#define NTSC TI_REGION_NTSC
#define PAL TI_REGION_PAL
#define SEEK_BUDGET TIM_SEEK_TICKS

/* Slots of the measurement image (build_tone). */
#define T_DIV6 1    /* AUDC C, no envelopes */
#define T_DIV2 2    /* AUDC 4 */
#define T_DIV31 3   /* AUDC 6 */
#define T_RELEASE 4 /* AUDC C, volume 15 15 10 5 0, loop 1, release 2 */
#define T_CAP 5     /* AUDC C, volume 15 15 12, release 2: never reaches 0 */
#define T_RAW 6     /* raw, AUDC 8 */
#define T_DC 7      /* AUDC 0: constant output */
#define T_UNDEFINED 8

static float g_out[TIM_MAX_TICK_FRAMES * 2];
static TiaImage g_song, g_moved, g_edited, g_tempo, g_short, g_pal, g_bad, g_tone[2], g_slots[3], g_unreachable;

static const double CLOCK_HZ[2] = {39375000.0 / 11.0, 3546894.0};
static const int LINES[2] = {TIM_LINES_NTSC, TIM_LINES_PAL};
static int64_t frame_clocks(int region) { return (int64_t)LINES[region] * TIM_CLOCKS_PER_LINE; }
static double audio_hz(int region) { return CLOCK_HZ[region] / TIM_AUDIO_DIVIDER; }
static double ticks_per_second(int region) { return CLOCK_HZ[region] / (double)frame_clocks(region); }

typedef struct Ref {
    const int* offsets;
    const unsigned char* regs;
    const unsigned char* vals;
    const short* pos;
    int region;
} Ref;

#define REF(name, region) {tia_ref_##name##_offsets, tia_ref_##name##_regs, tia_ref_##name##_vals, tia_ref_##name##_pos, region}
static const Ref REF_SONG = REF(song, NTSC);
static const Ref REF_EDITED = REF(edited, NTSC);
static const Ref REF_TEMPO = REF(tempo, NTSC);
static const Ref REF_PAL = REF(pal, PAL);
static const Ref REF_LIVE = REF(live, NTSC);

static double now_us(void) {
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec * 1e6 + t.tv_nsec / 1e3;
}

static uint64_t fnv(uint64_t h, const void* data, size_t n) {
    const uint8_t* p = (const uint8_t*)data;
    for (size_t i = 0; i < n; ++i) h = (h ^ p[i]) * 0x100000001B3ull;
    return h;
}

static void write_wav(const char* path, const float* data, int frames) {
    FILE* f = fopen(path, "wb");
    if (!f) return;
    int bytes = frames * 4;
    int hdr[] = {0x46464952, 36 + bytes, 0x45564157, 0x20746d66, 16, 0x00020001, RATE, RATE * 4, 0x00100004,
                 0x61746164, bytes};
    fwrite(hdr, sizeof hdr, 1, f);
    for (int i = 0; i < frames * 2; ++i) {
        float v = data[i] < -1 ? -1 : data[i] > 1 ? 1 : data[i];
        short s = (short)lrintf(v * 32767);
        fwrite(&s, 2, 1, f);
    }
    fclose(f);
}

/* Frequency from rising zero crossings of the left channel of interleaved stereo (mean removed). */
static double zero_cross_hz(const float* x, int n) {
    double mean = 0;
    for (int i = 0; i < n; ++i) mean += x[2 * i];
    mean /= n;
    int count = 0;
    double first_t = -1, last_t = 0;
    for (int i = 1; i < n; ++i) {
        double a = x[2 * (i - 1)] - mean, b = x[2 * i] - mean;
        if (a < 0 && b >= 0) {
            double t = (i - 1) + a / (a - b);
            if (first_t < 0) first_t = t;
            else {
                last_t = t;
                ++count;
            }
        }
    }
    return count ? count * (double)RATE / (last_t - first_t) : 0;
}

static double rms(const float* x, int frames) {
    double s = 0;
    for (int i = 0; i < frames * 2; ++i) s += (double)x[i] * x[i];
    return frames > 0 ? sqrt(s / (frames * 2.0)) : 0;
}

static double peak(const float* x, int frames) {
    double p = 0;
    for (int i = 0; i < frames * 2; ++i)
        if (fabs(x[i]) > p) p = fabs(x[i]);
    return p;
}

static int render(TiaMachine* m, int ticks, float** buf) {
    float* out = (float*)malloc((size_t)ticks * TIM_MAX_TICK_FRAMES * 2 * sizeof(float));
    int frames = 0;
    for (int t = 0; t < ticks; ++t) {
        int n = tim_tick(m, out + 2 * frames);
        if (n <= 0) break;
        frames += n;
    }
    *buf = out;
    return frames;
}

static int load(TiaImage* image, const uint8_t* bytes, size_t used, int region) {
    memset(image->bytes, 0, sizeof image->bytes);
    memcpy(image->bytes, bytes, used);
    return ti_load_image(image, region);
}

static int same_state(const TiaMachine* a, const TiaMachine* b) {
    for (int c = 0; c < TI_CHANNELS; ++c) {
        uint8_t x[10], y[10];
        tim_channel_state(a, c, x);
        tim_channel_state(b, c, y);
        if (memcmp(x, y, sizeof x)) return 0;
    }
    return 1;
}

/* ---- the trace hook: every batch the machine sends ------------------------------------------------------------ */

#define MAX_BATCHES 64
#define MAX_TRACE_WRITES 1024

typedef struct Batch {
    int64_t clock;
    int kind, first, n;
} Batch;

typedef struct Collect {
    int nb, nw, overflow;
    Batch b[MAX_BATCHES];
    TiWrite w[MAX_TRACE_WRITES];
} Collect;

static Collect g_col;

static void collect(void* ctx, int64_t clock, int kind, const TiWrite* w, int n) {
    Collect* c = (Collect*)ctx;
    if (c->nb >= MAX_BATCHES || c->nw + n > MAX_TRACE_WRITES) {
        c->overflow = 1;
        return;
    }
    Batch* b = &c->b[c->nb++];
    b->clock = clock;
    b->kind = kind;
    b->first = c->nw;
    b->n = n;
    memcpy(c->w + c->nw, w, sizeof *w * (size_t)n);
    c->nw += n;
}

static void clear(Collect* c) { c->nb = c->nw = c->overflow = 0; }

/* One tick through the machine, collecting its batches. */
static int traced_tick(TiaMachine* m) {
    clear(&g_col);
    return tim_tick(m, g_out);
}

static int ref_count(const Ref* r, int t) { return r->offsets[t + 1] - r->offsets[t]; }

/* Whether the collected batches of the last tick equal reference tick t: one batch at the tick's first clock. */
static int same_tick(const Collect* c, const Ref* r, int t) {
    if (c->overflow || c->nb != 1) return 0;
    const Batch* b = &c->b[0];
    if (b->kind != TIM_TRACE_TICK || b->clock != (int64_t)t * frame_clocks(r->region) || b->n != ref_count(r, t)) return 0;
    for (int i = 0; i < b->n; ++i) {
        const int j = r->offsets[t] + i;
        if (c->w[b->first + i].reg != r->regs[j] || c->w[b->first + i].val != r->vals[j]) return 0;
    }
    return 1;
}

static int same_reset(const TiPlayer* p) {
    if (p->writes != TIA_REF_RESET_WRITES) return 0;
    for (int i = 0; i < p->writes; ++i)
        if (p->write[i].reg != tia_ref_reset_regs[i] || p->write[i].val != tia_ref_reset_vals[i]) return 0;
    return 1;
}

/* First reference tick whose position is (order, row, 0), or -1. */
static int ref_row_start(const Ref* r, int order, int row) {
    for (int t = 0; t < TIA_REF_TICKS; ++t)
        if (r->pos[3 * t] == order && r->pos[3 * t + 1] == row && r->pos[3 * t + 2] == 0) return t;
    return -1;
}

static int pos_is(const TiaMachine* m, const Ref* r, int t) {
    int o, w, k;
    tim_position(m, &o, &w, &k);
    return o == r->pos[3 * t] && w == r->pos[3 * t + 1] && k == r->pos[3 * t + 2];
}

/* ---- the level probe ------------------------------------------------------------------------------------------- */

#define MAX_LEVELS (TIA_REF_LEVEL_TICKS * TIM_LINES_PAL * 2)

typedef struct Levels {
    int n, overflow;
    uint64_t hash;           /* of every (v0, v1) seen, for long runs */
    uint8_t v[MAX_LEVELS];   /* v0 | v1 << 4, the first MAX_LEVELS events */
    int64_t clock[MAX_LEVELS];
} Levels;

static Levels g_lv, g_lv2;

static void probe(void* ctx, int64_t clock, uint8_t v0, uint8_t v1) {
    Levels* l = (Levels*)ctx;
    const uint8_t v = (uint8_t)(v0 | v1 << 4);
    l->hash = fnv(l->hash, &v, 1);
    if (l->n >= MAX_LEVELS) {
        l->overflow = 1;
        return;
    }
    l->v[l->n] = v;
    l->clock[l->n] = clock;
    ++l->n;
}

static void clear_levels(Levels* l) {
    l->n = l->overflow = 0;
    l->hash = 0xCBF29CE484222325ull;
}

/* ---- images built here ----------------------------------------------------------------------------------------- */

static void put16(uint8_t* p, int v) {
    p[0] = (uint8_t)v;
    p[1] = (uint8_t)(v >> 8);
}

static void put32(uint8_t* p, uint32_t v) {
    for (int i = 0; i < 4; ++i) p[i] = (uint8_t)(v >> (8 * i));
}

/* One order of `rows` rows at `speed`, both channels' patterns at data offset 0, data[0 .. n). */
static void base_image(TiaImage* im, int region, int rows, int speed, const uint8_t* data, int n) {
    memset(im, 0, sizeof *im);
    uint8_t* b = im->bytes;
    memcpy(b, "TTIA", 4);
    b[TI_H_LAYOUT] = TI_LAYOUT;
    b[TI_H_REGION] = (uint8_t)region;
    b[TI_H_SPEED] = (uint8_t)speed;
    put16(b + TI_H_ORDERS, 1);
    b[TI_OFF_ROWS] = (uint8_t)rows;
    memcpy(b + TI_OFF_DATA, data, (size_t)n);
    put32(b + TI_H_DATA_SIZE, (uint32_t)n);
}

static void set_pattern(TiaImage* im, int order, int channel, int offset) {
    put16(im->bytes + TI_OFF_ORDERS + 2 * (TI_CHANNELS * order + channel), offset);
}

static uint8_t* record_of(TiaImage* im, int slot) { return im->bytes + TI_OFF_INSTRUMENTS + TI_INSTRUMENT_SIZE * (slot - 1); }

/* An instrument without envelopes (every envelope: length 0, loop and release $FF). */
static void put_instrument(TiaImage* im, int slot, int flags, int waveform) {
    uint8_t* r = record_of(im, slot);
    memset(r, 0, TI_INSTRUMENT_SIZE);
    r[TI_I_FLAGS] = (uint8_t)(TI_FLAG_DEFINED | flags);
    r[TI_I_WAVEFORM] = (uint8_t)waveform;
    for (int k = 0; k < TI_ENVELOPE_COUNT; ++k) {
        r[TI_I_ENVELOPES + TI_ENVELOPE_BYTES * k + 3] = TI_ENV_NONE;
        r[TI_I_ENVELOPES + TI_ENVELOPE_BYTES * k + 4] = TI_ENV_NONE;
    }
    if (im->bytes[TI_H_INSTRUMENTS] < slot) im->bytes[TI_H_INSTRUMENTS] = (uint8_t)slot;
}

static void put_envelope(TiaImage* im, int slot, int k, int offset, int length, int loop, int release) {
    uint8_t* e = record_of(im, slot) + TI_I_ENVELOPES + TI_ENVELOPE_BYTES * k;
    put16(e, offset);
    e[2] = (uint8_t)length;
    e[3] = (uint8_t)loop;
    e[4] = (uint8_t)release;
}

/* Auditions: data [0] the empty row, [1..5] volume 15 15 10 5 0 (loop 1, release 2), [6..8] volume 15 15 12
 * (release 2, the released part never reaching 0). */
static void build_tone(TiaImage* im, int region) {
    static const uint8_t data[] = {0x80, 15, 15, 10, 5, 0, 15, 15, 12};
    base_image(im, region, 1, 6, data, (int)sizeof data);
    put_instrument(im, T_DIV6, 0, 12);
    put_instrument(im, T_DIV2, 0, 4);
    put_instrument(im, T_DIV31, 0, 6);
    put_instrument(im, T_RELEASE, 0, 12);
    put_envelope(im, T_RELEASE, TI_ENV_VOLUME, 1, 5, 1, 2);
    put_instrument(im, T_CAP, 0, 12);
    put_envelope(im, T_CAP, TI_ENV_VOLUME, 6, 3, TI_ENV_NONE, 2);
    put_instrument(im, T_RAW, TI_FLAG_RAW, 8);
    put_instrument(im, T_DC, 0, 0);
    EXPECT(ti_load_image(im, region) == 0, "tone image (region %d) loads: %s", region, im->info.problem);
}

/* Slot identity: TIA 1 holds A-4 with slot 1, TIA 2 holds A-3 with slot 2, both AUDC C, byte-identical records; speed
 * 255. [0] slot 1 and 2 identical; [1] slot 2 edited to AUDC 4; [2] slot 2 removed (TIA 2's pattern no longer names
 * it: an empty row at data 6). */
static void build_slots(void) {
    static const uint8_t data[] = {0x03, A4, 1, 0x03, A4 - 12, 2, 0x80};
    for (int v = 0; v < 3; ++v) {
        TiaImage* im = &g_slots[v];
        base_image(im, NTSC, 1, 255, data, (int)sizeof data);
        set_pattern(im, 0, 1, v == 2 ? 6 : 3);
        put_instrument(im, 1, 0, 12);
        put_instrument(im, 2, 0, v == 1 ? 4 : 12);
        if (v == 2) memset(record_of(im, 2), 0, TI_INSTRUMENT_SIZE);
        EXPECT(ti_load_image(im, NTSC) == 0, "slot image %d loads: %s", v, im->info.problem);
    }
    EXPECT(!memcmp(record_of(&g_slots[0], 1), record_of(&g_slots[0], 2), TI_INSTRUMENT_SIZE), "slots 1 and 2 byte-identical");
}

/* One order of 4 rows at speed 1: row 0 breaks (D00) to the next order = order 0 (the loop), so rows 1-3 are never
 * reached, from the song start or the order's start. */
static void build_unreachable(void) {
    static const uint8_t data[] = {0x04, TI_FX_BREAK, 0x00, 0x82, 0x83};
    base_image(&g_unreachable, NTSC, 4, 1, data, (int)sizeof data);
    set_pattern(&g_unreachable, 0, 1, 4);
    EXPECT(ti_load_image(&g_unreachable, NTSC) == 0, "unreachable-row image loads: %s", g_unreachable.info.problem);
}

/* ---- tests ----------------------------------------------------------------------------------------------------- */

static void test_tables(void) {
    printf("tables\n");
    const double c0 = 440.0 * pow(2.0, -57.0 / 12.0);
    int formula = 1, semantics = 1, nearest = 1, worst_r = 0, worst_c = 0, worst_p = 0;
    for (int r = 0; r < TI_REGIONS; ++r) {
        for (int c = 0; c < TIP_CLASSES; ++c) {
            const int16_t* e = TIP_AUDF_EDGE[r][c];
            for (int k = 0; k < TIP_EDGES; ++k) {
                const double v = 768.0 * log2(audio_hz(r) / (TIP_PERIOD[c] * c0 * sqrt((k + 1.0) * (k + 2.0))));
                if ((int)ceil(v) != e[k]) formula = 0;
                if (k && e[k] >= e[k - 1]) semantics = 0;
                /* edge semantics: e[k] is the lowest pitch giving k; one below gives the next divider */
                if (tip_audf(r, c, e[k]) != k || tip_audf(r, c, e[k] - 1) != k + 1) semantics = 0;
            }
            if (tip_audf(r, c, 32767) != 0 || tip_audf(r, c, -32768) != TI_AUDF_MAX) semantics = 0;
            for (int p = TIP_PITCH_MIN; p <= TIP_PITCH_MAX; ++p) {
                const double f = c0 * pow(2.0, p / 768.0);
                const int a = tip_audf(r, c, p);
                const double err = fabs(log(audio_hz(r) / (TIP_PERIOD[c] * (a + 1.0)) / f));
                for (int k = 0; k <= TI_AUDF_MAX; ++k) {
                    if (fabs(log(audio_hz(r) / (TIP_PERIOD[c] * (k + 1.0)) / f)) < err - 1e-9) {
                        if (nearest) worst_r = r, worst_c = c, worst_p = p;
                        nearest = 0;
                    }
                }
            }
        }
    }
    EXPECT(formula, "TIP_AUDF_EDGE = ceil(768 log2(A / (P C0 sqrt((k + 1)(k + 2))))) for both regions");
    EXPECT(semantics, "tip_audf: the smallest k with pitch >= edge[k], else 31, for every region, class and k");
    EXPECT(nearest, "the chosen AUDF is the divider nearest in log frequency for every pitch (first miss: region %d class %d "
                    "pitch %d)",
           worst_r, worst_c, worst_p);
    EXPECT(tip_audf(NTSC, TIP_CLASS[12], A4 * 64) == 11 && tip_audf(PAL, TIP_CLASS[12], A4 * 64) == 11, "A-4 on AUDC C = AUDF 11");
    static const int8_t want_class[16] = {-1, 2, 5, 5, 0, 0, 3, 3, 6, 3, 3, -1, 1, 1, 4, 4};
    static const uint16_t want_period[TIP_CLASSES] = {2, 6, 15, 31, 93, 465, 511};
    EXPECT(!memcmp(TIP_CLASS, want_class, sizeof want_class) && !memcmp(TIP_PERIOD, want_period, sizeof want_period),
           "AUDC classes and periods as documented");
    int mix = 1, sine = 1;
    for (int s = 0; s <= 30; ++s)
        if (TIM_MIX[s] != (int)floor(0x7fff * (double)s / 30.0 * 60.0 / (30.0 + s))) mix = 0;
    for (int i = 0; i < 64; ++i)
        if (TIP_SINE[i] != (int)floor(127 * sin(2 * M_PI * i / 64) + 0.5)) sine = 0;
    EXPECT(mix && TIM_MIX[30] == 32767 && TIM_MIX[15] == 21844, "TIM_MIX = Stella's mixingTableEntry(s, 30)");
    EXPECT(sine, "TIP_SINE = floor(127 sin(2 pi i / 64) + 0.5)");
}

static int expect_offset(int rc, const TiaImage* im, int want, const char* what, int offset, int value) {
    EXPECT(rc != 0 && im->info.problem && im->info.problem_offset == want, "%s: byte %d = %d rejected at %d (got %s at %d)", what,
           offset, value, want, rc ? im->info.problem : "accepted", im->info.problem_offset);
    return rc;
}

/* The song with byte `offset` = value, loaded for NTSC: rejected at `want`. */
static void corrupt_at(int offset, int value, int want, const char* what) {
    memcpy(&g_bad, &g_song, sizeof g_bad);
    g_bad.bytes[offset] = (uint8_t)value;
    expect_offset(ti_load_image(&g_bad, NTSC), &g_bad, want, what, offset, value);
}
#define corrupt(offset, value, what) corrupt_at(offset, value, offset, what)

static void accepted(int offset, int value, const char* what) {
    memcpy(&g_bad, &g_song, sizeof g_bad);
    g_bad.bytes[offset] = (uint8_t)value;
    const int rc = ti_load_image(&g_bad, NTSC);
    EXPECT(rc == 0, "%s: byte %d = %d accepted (got %s at %d)", what, offset, value, rc ? g_bad.info.problem : "ok",
           g_bad.info.problem_offset);
}

/* A constructed image (g_bad, already filled) rejected at `want` (or accepted: want -1). */
static void constructed(const char* what, int want) {
    const int rc = ti_load_image(&g_bad, g_bad.bytes[TI_H_REGION]);
    if (want >= 0)
        EXPECT(rc != 0 && g_bad.info.problem_offset == want, "%s rejected at %d (got %s at %d)", what, want,
               rc ? g_bad.info.problem : "accepted", g_bad.info.problem_offset);
    else
        EXPECT(rc == 0, "%s accepted (got %s at %d)", what, rc ? g_bad.info.problem : "ok", g_bad.info.problem_offset);
}

static int ins_at(int slot, int field) { return TI_OFF_INSTRUMENTS + TI_INSTRUMENT_SIZE * (slot - 1) + field; }
static int env_at(int slot, int k) { return ins_at(slot, TI_I_ENVELOPES + TI_ENVELOPE_BYTES * k); }

/* Bit k set when an envelope of kind k of any defined slot of the song covers image byte `pos` (byte-identical
 * envelopes may be stored once for several slots and kinds: a value valid for one kind may not be for another). */
static int kinds_covering(int pos) {
    const uint8_t* s = g_song.bytes;
    int mask = 0;
    for (int n = 1; n <= g_song.info.instruments; ++n) {
        if (!(s[ins_at(n, TI_I_FLAGS)] & TI_FLAG_DEFINED)) continue;
        for (int k = 0; k < TI_ENVELOPE_COUNT; ++k) {
            const int at = env_at(n, k), length = s[at + 2], from = TI_OFF_DATA + ti_u16(s + at);
            if (length && pos >= from && pos < from + length) mask |= 1 << k;
        }
    }
    return mask;
}

static void test_images(void) {
    printf("images\n");
    const TiInfo* info = &g_song.info;
    const uint8_t* s = g_song.bytes;
    EXPECT(info->loaded == TI_LOADED && info->region == NTSC && g_pal.info.region == PAL, "song (NTSC) and PAL variant loaded");
    int rows_ok = 1;
    for (int o = 0; o < info->orders; ++o)
        if (info->rows[o] != (s[TI_OFF_ROWS + o] ? s[TI_OFF_ROWS + o] : 256) || info->start_speed[o] < 1) rows_ok = 0;
    EXPECT(rows_ok && info->start_speed[0] == info->speed && info->speed == s[TI_H_SPEED], "rows and start speeds derived");
    EXPECT(g_moved.info.orders == info->orders && !memcmp(g_moved.info.rows, info->rows, sizeof info->rows) &&
               !memcmp(g_moved.info.start_speed, info->start_speed, sizeof info->start_speed) &&
               memcmp(g_moved.bytes, g_song.bytes, sizeof g_song.bytes),
           "the moved image: the same song in another layout");
    /* region */
    memcpy(&g_bad, &g_song, sizeof g_bad);
    expect_offset(ti_load_image(&g_bad, PAL), &g_bad, TI_H_REGION, "the NTSC song loaded for PAL", TI_H_REGION, NTSC);
    memcpy(&g_bad, &g_pal, sizeof g_bad);
    expect_offset(ti_load_image(&g_bad, NTSC), &g_bad, TI_H_REGION, "the PAL song loaded for NTSC", TI_H_REGION, PAL);
    corrupt(TI_H_REGION, 2, "region 2");
    corrupt(TI_H_REGION, PAL, "region PAL for the NTSC loader");
    /* header */
    corrupt(TI_H_MAGIC, 'X', "magic");
    corrupt_at(TI_H_MAGIC + 3, 'B', TI_H_MAGIC, "magic (the field's first byte reported)");
    corrupt(TI_H_LAYOUT, 2, "layout");
    corrupt(TI_H_SPEED, 0, "speed 0");
    accepted(TI_H_SPEED, 255, "speed 255");
    corrupt(TI_H_INSTRUMENTS, 65, "instrument count 65");
    if (info->instruments >= 1 && s[ins_at(info->instruments, TI_I_FLAGS)])
        corrupt_at(TI_H_INSTRUMENTS, info->instruments - 1, ins_at(info->instruments, 0), "a record past the instrument count");
    if (!s[TI_H_ORDERS + 1]) corrupt(TI_H_ORDERS, 0, "order count 0");
    corrupt_at(TI_H_ORDERS + 1, 2, TI_H_ORDERS, "order count above 256");
    if (info->orders < 256) corrupt(TI_H_LOOP, info->orders, "loop order = order count");
    corrupt_at(TI_H_LOOP + 1, 1, TI_H_LOOP, "loop order above 255");
    corrupt(12, 1, "header reserved byte 12");
    corrupt(19, 1, "header reserved byte 19");
    corrupt_at(TI_H_DATA_SIZE + 3, 1, TI_H_DATA_SIZE, "data size above the region");
    corrupt(24, 1, "header reserved byte 24");
    corrupt(63, 1, "header reserved byte 63");
    /* tables past the order count */
    if (info->orders < 256) {
        corrupt(TI_OFF_ROWS + info->orders, 4, "rows of an order past the count");
        corrupt(TI_OFF_ORDERS + 2 * (TI_CHANNELS * info->orders + 1), 1, "pattern of an order past the count (channel 2)");
        corrupt_at(TI_OFF_ORDERS + 2 * (TI_CHANNELS * info->orders) + 1, 1, TI_OFF_ORDERS + 2 * (TI_CHANNELS * info->orders),
                   "pattern of an order past the count (high byte)");
    }
    corrupt_at(TI_OFF_ORDERS + 1, 0xFF, TI_OFF_ORDERS, "pattern offset past the data size");
    /* instruments: the first defined slot, then the first envelope of each shape found in the song */
    int slot = 0;
    for (int n = 1; n <= info->instruments && !slot; ++n)
        if (s[ins_at(n, TI_I_FLAGS)] & TI_FLAG_DEFINED) slot = n;
    EXPECT(slot > 0, "the song defines an instrument");
    if (slot) {
        corrupt(ins_at(slot, TI_I_FLAGS), 0x02, "flags without the defined bit");
        corrupt(ins_at(slot, TI_I_FLAGS), 0x88, "flags bit 3");
        corrupt(ins_at(slot, TI_I_FLAGS), 0xC0, "flags bit 6");
        accepted(ins_at(slot, TI_I_FLAGS), s[ins_at(slot, TI_I_FLAGS)] ^ TI_FLAG_RAW, "raw flag toggled");
        corrupt(ins_at(slot, TI_I_WAVEFORM), 16, "waveform 16");
        accepted(ins_at(slot, TI_I_WAVEFORM), 15, "waveform 15");
        corrupt(ins_at(slot, 2), 1, "instrument reserved byte 2");
        corrupt(ins_at(slot, 7), 1, "instrument reserved byte 7");
        corrupt(env_at(slot, TI_ENV_VOLUME) + 5, 1, "envelope reserved byte");
    }
    int empty_slot = 0, empty_k = 0, full_slot[TI_ENVELOPE_COUNT] = {0};
    for (int n = 1; n <= info->instruments; ++n) {
        if (!(s[ins_at(n, TI_I_FLAGS)] & TI_FLAG_DEFINED)) continue;
        for (int k = 0; k < TI_ENVELOPE_COUNT; ++k) {
            if (!s[env_at(n, k) + 2] && !empty_slot) empty_slot = n, empty_k = k;
            if (s[env_at(n, k) + 2] && !full_slot[k]) full_slot[k] = n;
        }
    }
    EXPECT(empty_slot > 0 && full_slot[TI_ENV_VOLUME] > 0, "the song has an empty and a volume envelope (fixture assumption)");
    if (empty_slot) {
        const int at = env_at(empty_slot, empty_k);
        corrupt(at, 1, "empty envelope with an offset");
        corrupt(at + 3, 0, "empty envelope with a loop");
        corrupt(at + 4, 1, "empty envelope with a release");
    }
    for (int k = 0; k < TI_ENVELOPE_COUNT; ++k) {
        if (!full_slot[k]) continue;
        const int at = env_at(full_slot[k], k), length = s[at + 2], data = TI_OFF_DATA + ti_u16(s + at);
        corrupt(at + 3, length, "envelope loop = length");
        if (s[at + 3] == TI_ENV_NONE) corrupt(at + 4, length, "envelope release = length");
        if (s[at + 3] == TI_ENV_NONE) corrupt(at + 4, 0, "envelope release 0");
        corrupt_at(at + 1, 0xFF, at, "envelope offset past the data size");
        if (k == TI_ENV_VOLUME) {
            corrupt(data, 16, "volume envelope value 16");
            if (kinds_covering(data) == 1 << k) accepted(data, 15, "volume envelope value 15");
        }
        if (k == TI_ENV_ARPEGGIO) {
            corrupt(data, 64, "arpeggio envelope value 64");
            corrupt(data, 0xBF, "arpeggio envelope value -65");
            if (kinds_covering(data) == 1 << k) accepted(data, 0xC0, "arpeggio envelope value -64");
        }
        if (k == TI_ENV_PITCH) {
            if (kinds_covering(data) == 1 << k) accepted(data, 0x80, "pitch envelope value -128");
            if (kinds_covering(data) == 1 << k) accepted(data, 0x7F, "pitch envelope value 127");
        }
        if (k == TI_ENV_WAVEFORM) {
            corrupt(data, 16, "waveform envelope value 16");
            if (kinds_covering(data) == 1 << k) accepted(data, 15, "waveform envelope value 15");
        }
    }
    /* patterns (byte offsets from the generator) */
    corrupt(TIA_OFFSET_MASK, 0x20, "row mask bit 5");
    corrupt(TIA_OFFSET_MASK, 0x40, "row mask bit 6");
    corrupt(TIA_OFFSET_MASK, 0x00, "row mask 0");
    corrupt(TIA_OFFSET_MASK, 0x0F, "row mask with three effects");
    corrupt(TIA_OFFSET_NOTE, TI_NOTE_MAX + 1, "note 120");
    corrupt(TIA_OFFSET_NOTE, 0xFF, "note $FF");
    accepted(TIA_OFFSET_NOTE, TI_NOTE_OFF, "OFF");
    accepted(TIA_OFFSET_NOTE, TI_NOTE_MIN, "C-0");
    accepted(TIA_OFFSET_NOTE, TI_NOTE_MAX, "B-9");
    corrupt(TIA_OFFSET_INST, 0, "instrument 0");
    corrupt(TIA_OFFSET_INST, 65, "instrument 65");
    if (info->instruments < TI_MAX_INSTRUMENTS) corrupt(TIA_OFFSET_INST, info->instruments + 1, "instrument past the count");
    corrupt(TIA_OFFSET_EFFECT, 36, "effect code 36");
    static const int unknown[] = {5, 6, 7, 8, 9, 14, 17, 18, 19, 20, 21, 22, 23, 24, 26, 27, 29, 30, 31, 33, 34, 35};
    for (size_t i = 0; i < sizeof unknown / sizeof unknown[0]; ++i) corrupt(TIA_OFFSET_EFFECT, unknown[i], "code without an effect");
    corrupt(TIA_OFFSET_PARAM_B, info->orders, "Bxx = order count");
    accepted(TIA_OFFSET_PARAM_B, info->orders - 1, "Bxx to the last order");
    corrupt(TIA_OFFSET_PARAM_C, 0x10, "C10");
    accepted(TIA_OFFSET_PARAM_C, 0x0F, "C0F");
    corrupt(TIA_OFFSET_PARAM_F, 0x00, "F00");
    accepted(TIA_OFFSET_PARAM_F, 0xFF, "FFF");
    corrupt(TIA_OFFSET_PARAM_W, 0x10, "W10");
    accepted(TIA_OFFSET_PARAM_W, 0x0F, "W0F");

    /* Constructed images for the checks a single byte of the song cannot reach. */
    static const uint8_t empty_row[] = {0x80};
    base_image(&g_bad, NTSC, 2, 6, empty_row, 1);
    constructed("a pattern decoding past the data", TI_OFF_DATA + 1);
    {
        static const uint8_t data[] = {0x01};
        base_image(&g_bad, NTSC, 1, 6, data, 1);
        constructed("a row whose note byte is past the data", TI_OFF_DATA + 1);
    }
    base_image(&g_bad, NTSC, 1, 6, empty_row, 1);
    put32(g_bad.bytes + TI_H_DATA_SIZE, TI_DATA_CAPACITY + 1);
    constructed("data size 62145", TI_H_DATA_SIZE);
    base_image(&g_bad, NTSC, 1, 6, empty_row, 1);
    put32(g_bad.bytes + TI_H_DATA_SIZE, TI_DATA_CAPACITY);
    constructed("data size 62144", -1);
    {
        /* two 128-row runs: a full 256-row order */
        static const uint8_t runs[] = {0xFF, 0xFF};
        base_image(&g_bad, PAL, 0, 255, runs, 2);
        constructed("a PAL image of one 256-row order at speed 255", -1);
        /* 256 orders, every pattern the same runs */
        base_image(&g_bad, NTSC, 1, 1, runs, 2);
        put16(g_bad.bytes + TI_H_ORDERS, 256);
        put16(g_bad.bytes + TI_H_LOOP, 255);
        memset(g_bad.bytes + TI_OFF_ROWS, 0, 256);
        constructed("256 orders of 256 rows", -1);
        EXPECT(g_bad.info.rows[255] == 256, "rows byte 0 = 256");
    }
    {
        /* the start speed of each order: header, then the last Fxx of earlier orders (rows, channels, columns) */
        static const uint8_t data[] = {0x08, TI_FX_SPEED, 3, TI_FX_SPEED, 4, 0x04, TI_FX_SPEED, 5, 0x80};
        base_image(&g_bad, NTSC, 1, 7, data, (int)sizeof data);
        put16(g_bad.bytes + TI_H_ORDERS, 3);
        g_bad.bytes[TI_OFF_ROWS + 1] = g_bad.bytes[TI_OFF_ROWS + 2] = 1;
        set_pattern(&g_bad, 0, 1, 5);   /* order 0: F03 F04 on TIA 1, F05 on TIA 2 */
        set_pattern(&g_bad, 1, 0, 8);
        set_pattern(&g_bad, 1, 1, 8);
        set_pattern(&g_bad, 2, 0, 8);
        set_pattern(&g_bad, 2, 1, 8);
        constructed("speed effects", -1);
        EXPECT(g_bad.info.start_speed[0] == 7 && g_bad.info.start_speed[1] == 5 && g_bad.info.start_speed[2] == 5,
               "start speeds 7 5 5 (%d %d %d)", g_bad.info.start_speed[0], g_bad.info.start_speed[1], g_bad.info.start_speed[2]);
    }

    memcpy(&g_bad, &g_song, sizeof g_bad);
    EXPECT(ti_load_image(&g_bad, NTSC) == 0 && !memcmp(&g_bad.info, &g_song.info, sizeof g_bad.info), "loading is a pure function");
}

static void fprint_writes(FILE* f, const TiWrite* w, int n) {
    for (int i = 0; i < n; ++i) fprintf(f, " %02X=%02X", w[i].reg, w[i].val);
}

/* Plays `image` from the start and compares every tick with `ref`; writes the trace file when `trace` is given. */
static void play_reference(const TiaImage* image, const Ref* ref, const char* what, FILE* trace) {
    TiaMachine* m = tim_create(RATE, ref->region);
    int mode = -1;
    EXPECT(tim_start(m, image, 0, 0, SEEK_BUDGET, &mode) == TIM_OK && mode == TIM_SEEK_FROM_START, "%s: start", what);
    EXPECT(same_reset(tim_player(m)), "%s: reset batch = reference (%d writes, reference %d)", what, tim_player(m)->writes,
           TIA_REF_RESET_WRITES);
    tim_set_trace(m, collect, &g_col);
    int mismatches = 0, first = -1, position_errors = 0, writes = 0, max_writes = 0;
    for (int t = 0; t < TIA_REF_TICKS; ++t) {
        if (!pos_is(m, ref, t)) ++position_errors;
        int o, r, k;
        tim_position(m, &o, &r, &k);
        traced_tick(m);
        if (!same_tick(&g_col, ref, t)) {
            if (first < 0) first = t;
            ++mismatches;
        }
        if (g_col.nb) {
            writes += g_col.b[0].n;
            if (g_col.b[0].n > max_writes) max_writes = g_col.b[0].n;
        }
        if (trace) {
            fprintf(trace, "%d %d %d:", o, r, k);
            if (g_col.nb) fprint_writes(trace, g_col.w + g_col.b[0].first, g_col.b[0].n);
            fputc('\n', trace);
        }
    }
    tim_set_trace(m, NULL, NULL);
    EXPECT(mismatches == 0, "%s: writes and clocks = reference player in all %d ticks (%d differ, first at tick %d)", what,
           TIA_REF_TICKS, mismatches, first);
    if (first >= 0) {
        printf("  first difference at tick %d; reference:", first);
        for (int j = ref->offsets[first]; j < ref->offsets[first + 1]; ++j) printf(" %02X=%02X", ref->regs[j], ref->vals[j]);
        printf("\n");
    }
    EXPECT(position_errors == 0, "%s: positions = reference in every tick (%d differ)", what, position_errors);
    printf("  %s: %d ticks, %d writes (max %d per tick)\n", what, TIA_REF_TICKS, writes, max_writes);
    tim_destroy(m);
}

static void test_reference(const char* dir) {
    printf("reference player\n");
    char path[512];
    snprintf(path, sizeof path, "%s/tia_trace.txt", dir);
    FILE* trace = fopen(path, "w");
    play_reference(&g_song, &REF_SONG, "song", trace);
    if (trace) fclose(trace);
    play_reference(&g_moved, &REF_SONG, "moved (= song)", NULL);
    play_reference(&g_edited, &REF_EDITED, "edited", NULL);
    play_reference(&g_tempo, &REF_TEMPO, "tempo", NULL);
    play_reference(&g_pal, &REF_PAL, "PAL", NULL);
    snprintf(path, sizeof path, "%s/tia_song.bin", dir); /* the image, for tools/audio/tia/tia_reference_check.py */
    FILE* f = fopen(path, "wb");
    if (f) {
        fwrite(g_song.bytes, 1, sizeof g_song.bytes, f);
        fclose(f);
    }
}

/* Channel levels after every phase 1 and the counter states, against the reference chip. */
static void levels(const TiaImage* image, int region, const unsigned char* want, size_t n_want, const unsigned char* state,
                   const char* what) {
    TiaMachine* m = tim_create(RATE, region);
    int mode;
    tim_start(m, image, 0, 0, SEEK_BUDGET, &mode);
    clear_levels(&g_lv);
    tim_set_level_probe(m, probe, &g_lv);
    for (int t = 0; t < TIA_REF_LEVEL_TICKS; ++t) tim_tick(m, g_out);
    tim_set_level_probe(m, NULL, NULL);
    const int per_tick = 2 * LINES[region];
    int clocks_ok = !g_lv.overflow && g_lv.n == TIA_REF_LEVEL_TICKS * per_tick;
    for (int i = 0; clocks_ok && i < g_lv.n; ++i) {
        const int64_t want_clock = (int64_t)(i / per_tick) * frame_clocks(region) + (int64_t)((i / 2) % LINES[region]) * 228 +
                                   (i % 2 ? TIM_PHASE1_B : TIM_PHASE1_A);
        if (g_lv.clock[i] != want_clock) clocks_ok = 0;
    }
    EXPECT(clocks_ok, "%s: %d phase-1 events at line clocks 37 and 149 of every line (%d)", what, TIA_REF_LEVEL_TICKS * per_tick,
           g_lv.n);
    int first = -1;
    for (int i = 0; i < g_lv.n && i < (int)n_want; ++i)
        if (g_lv.v[i] != want[i]) {
            first = i;
            break;
        }
    EXPECT(g_lv.n == (int)n_want && first < 0, "%s: channel levels = reference chip after every phase 1 (%d events, reference %d, "
                                               "first difference %d)",
           what, g_lv.n, (int)n_want, first);
    uint8_t got[20];
    tim_channel_state(m, 0, got);
    tim_channel_state(m, 1, got + 10);
    EXPECT(!memcmp(got, state, 20), "%s: both channels' counter states = reference chip after %d ticks", what, TIA_REF_LEVEL_TICKS);
    tim_destroy(m);
}

static void test_levels(void) {
    printf("chip levels\n");
    levels(&g_song, NTSC, tia_ref_song_levels, sizeof tia_ref_song_levels, tia_ref_song_state, "NTSC");
    levels(&g_pal, PAL, tia_ref_pal_levels, sizeof tia_ref_pal_levels, tia_ref_pal_state, "PAL");
}

static void test_frames(void) {
    printf("frames per tick\n");
    for (int region = 0; region < TI_REGIONS; ++region) {
        TiaMachine* m = tim_create(RATE, region);
        int mode, lo = 1 << 30, hi = 0;
        long total = 0;
        tim_start(m, region == PAL ? &g_pal : &g_song, 0, 0, SEEK_BUDGET, &mode);
        for (int t = 0; t < 600; ++t) {
            const int n = tim_tick(m, g_out);
            EXPECT(n == tim_frames(m), "tim_frames = the tick's frames");
            if (n < lo) lo = n;
            if (n > hi) hi = n;
            total += n;
        }
        const double exact = 600.0 * RATE / ticks_per_second(region);
        const int want_lo = region == PAL ? 962 : 801;
        EXPECT(lo >= want_lo && hi <= want_lo + 1, "%s: %d..%d frames per tick at 48 kHz (%d/%d)", region ? "PAL" : "NTSC", lo, hi,
               want_lo, want_lo + 1);
        EXPECT(fabs(total - exact) <= 1.0, "%s: 600 ticks = %ld frames (exact %.2f)", region ? "PAL" : "NTSC", total, exact);
        tim_destroy(m);
        m = tim_create(TIM_MAX_SAMPLE_RATE, region);
        tim_start(m, region == PAL ? &g_pal : &g_song, 0, 0, SEEK_BUDGET, &mode);
        hi = 0;
        for (int t = 0; t < 120; ++t) {
            const int n = tim_tick(m, g_out);
            if (n > hi) hi = n;
        }
        EXPECT(hi <= (int)TIM_MAX_TICK_FRAMES && hi > 0, "%s at 96 kHz: at most %d frames per tick (%d)", region ? "PAL" : "NTSC",
               (int)TIM_MAX_TICK_FRAMES, hi);
        tim_destroy(m);
    }
    EXPECT(tim_create(7999, NTSC) == NULL && tim_create(TIM_MAX_SAMPLE_RATE + 1, NTSC) == NULL && tim_create(RATE, 2) == NULL,
           "unsupported rates and regions refused");
}

static void test_audio(const char* dir) {
    printf("audio\n");
    for (int region = 0; region < TI_REGIONS; ++region) {
        const int ticks = (int)lround(30 * ticks_per_second(region));
        uint64_t hash[2] = {0, 0};
        for (int pass = 0; pass < 2; ++pass) {
            TiaMachine* m = tim_create(RATE, region);
            int mode;
            tim_start(m, region == PAL ? &g_pal : &g_song, 0, 0, SEEK_BUDGET, &mode);
            float* buf;
            const double t0 = now_us();
            const int frames = render(m, ticks, &buf);
            const double us = (now_us() - t0) / ticks;
            hash[pass] = fnv(0xCBF29CE484222325ull, buf, (size_t)frames * 2 * sizeof(float));
            if (pass == 0) {
                const double r = rms(buf, frames), pk = peak(buf, frames);
                const double exact = ticks * (double)RATE / ticks_per_second(region);
                EXPECT(fabs(frames - exact) <= 1.0, "%s: %d ticks = %d frames (exact %.1f)", region ? "PAL" : "NTSC", ticks, frames,
                       exact);
                EXPECT(r > 0.01, "%s: non-silent (rms %.4f; assumption: > 0.01)", region ? "PAL" : "NTSC", r);
                int same_sides = 1;
                for (int i = 0; i < frames; ++i)
                    if (buf[2 * i] != buf[2 * i + 1]) same_sides = 0;
                EXPECT(same_sides, "%s: mono on both sides", region ? "PAL" : "NTSC");
                char path[512];
                snprintf(path, sizeof path, "%s/%s", dir, region ? "tia_song_pal.wav" : "tia_song.wav");
                write_wav(path, buf, frames);
                printf("  %s 30 s: rms %.4f, peak %.4f, %.1f us per tick\n", region ? "PAL" : "NTSC", r, pk, us);
            }
            free(buf);
            tim_destroy(m);
        }
        EXPECT(hash[0] == hash[1], "%s: bit-identical on a second start", region ? "PAL" : "NTSC");
    }
}

/* Consumer regression for the full 0..1 DAC range, not just the demo's peak.
 * A second blip runs at 1/16 level, independently scheduled from the raw chip
 * probe and the rational Stella mixing formula (not TIM_MIX or tim_level).
 * Its PCM *4 must agree with the production 1/4 path within 16 PCM units:
 * independent integer level/interpolation/high-pass rounding, not clipping.
 * This catches post-read attenuation as well as missing pre-blip headroom.
 * The existing independent chip/reference tests cover the probed waveform. */
static void quiet_mix(blip_t* blip, int* previous, unsigned clock, int sum) {
    const int level = (65534 * sum / (30 + sum)) / 16;
    blip_add_delta(blip, clock, level - *previous);
    *previous = level;
}

static void test_headroom(void) {
    printf("resampler headroom\n");
    static const int rates[] = {8000, 44100, 48000, 96000};
    static const int waves[] = {0, 4, 8, 12, 15};
    static const uint8_t notes[] = {0x03, A4, 1};
    static TiaImage image;
    static short quiet[TIM_MAX_TICK_FRAMES];
    static float control[TIM_MAX_TICK_FRAMES * 2];
    for (int region = NTSC; region <= PAL; ++region) {
        for (size_t ri = 0; ri < sizeof rates / sizeof rates[0]; ++ri) {
            for (size_t wi = 0; wi < sizeof waves / sizeof waves[0]; ++wi) {
                const int rate = rates[ri], wave = waves[wi];
                base_image(&image, region, 1, 255, notes, (int)sizeof notes);
                put_instrument(&image, 1, 0, wave);
                EXPECT(ti_load_image(&image, region) == 0, "loud image region %d AUDC %X loads", region, wave);
                TiaMachine* m = tim_create((uint32_t)rate, region);
                TiaMachine* unmuted = tim_create((uint32_t)rate, region);
                blip_t* reference = blip_new(TIM_MAX_TICK_FRAMES + 64);
                EXPECT(m && unmuted && reference, "headroom machines allocated");
                if (!m || !unmuted || !reference) {
                    tim_destroy(m);
                    tim_destroy(unmuted);
                    blip_delete(reference);
                    continue;
                }
                blip_set_rates(reference, CLOCK_HZ[region], rate);
                blip_clear(reference);
                int mode, previous = 0, sum = 0, bad = 0, states = 1, rails = 0, pcm = 1;
                double error = 0, peaks[4] = {0}, settled = 0;
                EXPECT(tim_start(m, &image, 0, 0, SEEK_BUDGET, &mode) == TIM_OK &&
                           tim_start(unmuted, &image, 0, 0, SEEK_BUDGET, &mode) == TIM_OK,
                       "headroom playback starts");
                tim_set_level_probe(m, probe, &g_lv);
                for (int t = 0; t < 60; ++t) {
                    const int muted = (t >= 15 && t < 30) || t >= 45;
                    tim_mute(m, 0, muted);
                    tim_mute(m, 1, muted);
                    clear_levels(&g_lv);
                    const int n = tim_tick(m, g_out);
                    const int nc = tim_tick(unmuted, control);
                    if (n <= 0 || n != nc || g_lv.overflow || g_lv.n != 2 * LINES[region]) ++bad;
                    if (!same_state(m, unmuted)) states = 0;
                    /* No register changes after the first key-on in this 255-tick row;
                     * reset starts with both output bits zero. Mute acts at clock 0. */
                    quiet_mix(reference, &previous, 0, muted ? 0 : sum);
                    for (int k = 0; k < g_lv.n; ++k) {
                        const int v0 = g_lv.v[k] & 15, v1 = g_lv.v[k] >> 4;
                        if ((v0 != 0 && v0 != 15) || (v1 != 0 && v1 != 15)) ++bad;
                        sum = v0 + v1;
                        quiet_mix(reference, &previous,
                                  (unsigned)(g_lv.clock[k] - (int64_t)t * frame_clocks(region) + 1),
                                  muted ? 0 : sum);
                    }
                    if (tim_level(m) != (muted ? 0 : 65534 * sum / (30 + sum))) ++bad;
                    blip_end_frame(reference, (unsigned)frame_clocks(region));
                    const int nr = blip_read_samples(reference, quiet, TIM_MAX_TICK_FRAMES, 0);
                    if (nr != n) ++bad;
                    for (int i = 0; i < n; ++i) {
                        const double sample = g_out[2 * i], raw = sample * 32768.0;
                        if (!isfinite(sample) || sample != g_out[2 * i + 1] || raw != floor(raw)) pcm = 0;
                        if (raw <= -32768 || raw >= 32767) ++rails;
                        if (fabs(sample) > peaks[t / 15]) peaks[t / 15] = fabs(sample);
                        if ((t == 29 || t == 59) && fabs(sample) > settled) settled = fabs(sample);
                        if (i < nr && fabs(raw - 4.0 * quiet[i]) > error) error = fabs(raw - 4.0 * quiet[i]);
                    }
                }
                EXPECT(bad == 0 && states && pcm, "%s %d Hz AUDC %X: frame grid, full chip levels, mute-independent state, "
                       "unscaled nonlinear mix and mono PCM preserved (%d bad)", region ? "PAL" : "NTSC", rate, wave, bad);
                EXPECT(rails == 0 && peaks[0] < 0.66 && peaks[1] < 0.66 && peaks[2] < 0.66 && peaks[3] < 0.66,
                       "%s %d Hz AUDC %X: no int16 rails (%d), loud peaks %.6f / %.6f",
                       region ? "PAL" : "NTSC", rate, wave, rails, peaks[0], peaks[2]);
                EXPECT(peaks[0] > 0.05 && peaks[2] > 0.05 && settled < 0.02,
                       "%s %d Hz AUDC %X: audible start/unmute and decaying mute tails (%.6f / %.6f, tail %.6f)",
                       region ? "PAL" : "NTSC", rate, wave, peaks[0], peaks[2], settled);
                EXPECT(error <= 16.0, "%s %d Hz AUDC %X: attenuated independent resampler oracle (max error %.1f PCM units)",
                       region ? "PAL" : "NTSC", rate, wave, error);
                tim_destroy(m);
                tim_destroy(unmuted);
                blip_delete(reference);
            }
        }
    }
}

/* One audition note's frequency (zero crossings after 0.1 s). */
static double measure(int region, int channel, int note, int slot, int fine, int ticks, const char* wav) {
    TiaMachine* m = tim_create(RATE, region);
    EXPECT(tim_audition(m, &g_tone[region], channel, note, slot, fine) == TIM_OK, "audition %d on slot %d", note, slot);
    float* buf;
    const int frames = render(m, ticks, &buf);
    const double hz = zero_cross_hz(buf + 2 * (RATE / 10), frames - RATE / 10);
    if (wav) write_wav(wav, buf, frames);
    free(buf);
    tim_destroy(m);
    return hz;
}

static void test_pitch(const char* dir) {
    printf("pitch\n");
    char path[512];
    for (int region = 0; region < TI_REGIONS; ++region) {
        const char* name = region ? "PAL" : "NTSC";
        snprintf(path, sizeof path, "%s/%s", dir, region ? "tia_tone_pal.wav" : "tia_tone.wav");
        const double a4 = measure(region, 0, A4, T_DIV6, 0, region ? 100 : 120, path);
        const double want = audio_hz(region) / (6.0 * 12.0);
        const double literal = region ? 432.13 : 436.10;
        EXPECT(fabs(a4 - want) < 0.3 && fabs(a4 - literal) < 0.3, "%s: A-4 on AUDC C measured %.3f Hz (A / (6 x 12) = %.3f; "
                                                                  "assumption: +-0.3)",
               name, a4, want);
        /* div 2: C-7; div 31: C-3, against A / (P (AUDF + 1)) */
        static const int notes[2] = {84, 36}, slots[2] = {T_DIV2, T_DIV31}, periods[2] = {2, 31}, classes[2] = {0, 3};
        for (int i = 0; i < 2; ++i) {
            const int audf = tip_audf(region, classes[i], notes[i] * 64);
            const double expect = audio_hz(region) / (periods[i] * (audf + 1.0));
            const double got = measure(region, 1, notes[i], slots[i], 0, 120, NULL);
            EXPECT(fabs(got / expect - 1) < 0.005, "%s: note %d on div %d = AUDF %d: %.2f Hz (%.2f; assumption: 0.5%%)", name,
                   notes[i], periods[i], audf, got, expect);
        }
        printf("  %s: A-4 %.3f Hz (%.3f)\n", name, a4, want);
    }
    /* raw: AUDF = 31 - note mod 32, fine pitch ignored; constant waveform: no AUDF write */
    TiaMachine* m = tim_create(RATE, NTSC);
    const TiPlayer* p = tim_player(m);
    tim_audition(m, &g_tone[NTSC], 0, 40, T_RAW, 64);
    tim_tick(m, g_out);
    EXPECT(p->ch[0].audf == 31 - 40 % 32 && p->ch[0].audc == 8, "raw note 40: AUDF %d (23), AUDC %d", p->ch[0].audf, p->ch[0].audc);
    tim_audition(m, &g_tone[NTSC], 0, TI_NOTE_MAX, T_RAW, 0);
    tim_tick(m, g_out);
    EXPECT(p->ch[0].audf == 31 - TI_NOTE_MAX % 32, "raw B-9: AUDF %d (%d)", p->ch[0].audf, 31 - TI_NOTE_MAX % 32);
    tim_set_trace(m, collect, &g_col);
    tim_audition(m, &g_tone[NTSC], 1, A4, T_DC, 0);
    traced_tick(m);
    int audf_writes = 0;
    for (int i = 0; i < g_col.nw; ++i)
        if (g_col.w[i].reg == TI_REG_AUDF0 || g_col.w[i].reg == TI_REG_AUDF1) ++audf_writes;
    EXPECT(audf_writes == 0 && p->ch[1].audc == 0 && p->ch[1].audv == 15, "AUDC 0: no AUDF write, AUDV 15 (%d AUDF writes)",
           audf_writes);
    tim_set_trace(m, NULL, NULL);
    tim_destroy(m);
}

static void test_seek(void) {
    printf("seek\n");
    /* Targets: the rows straight play is in at these ticks (each sought at its first arrival). */
    static const int at_ticks[] = {5, 40, 120, 250, 400, 600, 900, 1200};
    TiaMachine* m = tim_create(RATE, NTSC);
    for (size_t i = 0; i < sizeof at_ticks / sizeof at_ticks[0]; ++i) {
        if (at_ticks[i] >= TIA_REF_TICKS) continue;
        const int o = REF_SONG.pos[3 * at_ticks[i]], r = REF_SONG.pos[3 * at_ticks[i] + 1], k = ref_row_start(&REF_SONG, o, r);
        EXPECT(k >= 0, "target %d/%d is in the reference", o, r);
        if (k < 0) continue;
        int mode = -1;
        const double t0 = now_us();
        EXPECT(tim_start(m, &g_song, o, r, SEEK_BUDGET, &mode) == TIM_OK && mode == TIM_SEEK_FROM_START, "seek %d/%d", o, r);
        const double us = now_us() - t0;
        EXPECT(pos_is(m, &REF_SONG, k), "lands on %d/%d tick 0", o, r);
        EXPECT(tim_clock(m) == (int64_t)k * frame_clocks(NTSC), "the clock counts the %d seek ticks", k);
        tim_set_trace(m, collect, &g_col);
        int bad = 0;
        const int n = TIA_REF_TICKS - k < 200 ? TIA_REF_TICKS - k : 200;
        for (int j = 0; j < n; ++j) {
            if (!pos_is(m, &REF_SONG, k + j)) ++bad;
            traced_tick(m);
            if (!same_tick(&g_col, &REF_SONG, k + j)) ++bad;
        }
        tim_set_trace(m, NULL, NULL);
        EXPECT(bad == 0, "seek %d/%d: %d ticks of writes, clocks and positions = straight play (%d differ)", o, r, n, bad);
        /* Sound and counter states from the target = straight play from the same tick, bit for bit. */
        TiaMachine* a = tim_create(RATE, NTSC);
        tim_start(a, &g_song, 0, 0, SEEK_BUDGET, &mode);
        for (int j = 0; j < k; ++j) tim_tick(a, g_out);
        tim_start(m, &g_song, o, r, SEEK_BUDGET, &mode);
        int states = same_state(a, m), sound = 1;
        static float x[TIM_MAX_TICK_FRAMES * 2], y[TIM_MAX_TICK_FRAMES * 2];
        for (int j = 0; j < 60; ++j) {
            const int fx = tim_tick(a, x), fy = tim_tick(m, y);
            if (fx != fy || memcmp(x, y, sizeof(float) * 2 * (size_t)fx)) sound = 0;
            if (!same_state(a, m)) states = 0;
        }
        EXPECT(sound, "seek %d/%d (%d ticks): sound = straight play, bit for bit", o, r, k);
        EXPECT(states, "seek %d/%d: channel states = straight play at the target and every tick after", o, r);
        printf("  %d/%d: %d ticks fast-forwarded in %.0f us\n", o, r, k, us);
        tim_destroy(a);
    }
    /* Order fallback: a budget below the ticks straight play needs; a row 0 is always reached from its order's start. */
    int target = -1;
    for (int t = TIA_REF_TICKS - 1; t > 20 && target < 0; --t)
        if (REF_SONG.pos[3 * t + 1] == 0 && REF_SONG.pos[3 * t + 2] == 0 && ref_row_start(&REF_SONG, REF_SONG.pos[3 * t], 0) > 20)
            target = REF_SONG.pos[3 * t];
    EXPECT(target >= 0, "an order whose row 0 straight play reaches after tick 20");
    if (target >= 0) {
        int mode = -1, o, r, t;
        EXPECT(tim_start(m, &g_song, target, 0, 10, &mode) == TIM_OK && mode == TIM_SEEK_FROM_ORDER, "budget 10: order fallback");
        tim_position(m, &o, &r, &t);
        EXPECT(o == target && r == 0 && t == 0 && tim_player(m)->speed == g_song.info.start_speed[target],
               "fallback lands on %d/0 with the order's start speed (%d/%d/%d)", target, o, r, t);
        const int rows = g_song.info.rows[target];
        if (rows > 1) {
            /* budget 0: the order fallback replays the order's rows, unless the row sits behind a jump of its order */
            const int rc = tim_start(m, &g_song, target, rows - 1, 0, &mode);
            tim_position(m, &o, &r, &t);
            EXPECT(rc == TIM_ERR_IMAGE || (mode == TIM_SEEK_FROM_ORDER && o == target && r == rows - 1 && t == 0),
                   "budget 0, last row of order %d: replayed from the order start (%d/%d/%d) or unreachable", target, o, r, t);
        }
    }
    {
        int mode = -1;
        TiaMachine* u = tim_create(RATE, NTSC);
        EXPECT(tim_start(u, &g_unreachable, 0, 2, SEEK_BUDGET, &mode) == TIM_ERR_IMAGE, "a row behind a D00 is unreachable");
        EXPECT(tim_start(u, &g_unreachable, 0, 0, SEEK_BUDGET, &mode) == TIM_OK && mode == TIM_SEEK_FROM_START, "its row 0 is");
        tim_destroy(u);
    }
    int mode;
    EXPECT(tim_start(m, &g_song, g_song.info.orders, 0, SEEK_BUDGET, &mode) == TIM_ERR_IMAGE, "order past the song rejected");
    EXPECT(tim_start(m, &g_song, 0, g_song.info.rows[0], SEEK_BUDGET, &mode) == TIM_ERR_IMAGE, "row past the order rejected");
    EXPECT(tim_start(m, &g_song, -1, 0, SEEK_BUDGET, &mode) == TIM_ERR_IMAGE, "order -1 rejected");
    EXPECT(tim_start(m, &g_pal, 0, 0, SEEK_BUDGET, &mode) == TIM_ERR_IMAGE, "a PAL image on the NTSC machine rejected");
    EXPECT(tim_tick(m, g_out) == 0, "nothing loaded after a failed start: tick 0");
    tim_destroy(m);
}

static void test_mute(void) {
    printf("mute\n");
    TiaMachine* a = tim_create(RATE, NTSC);
    TiaMachine* b = tim_create(RATE, NTSC);
    int mode, bad_states = 0, bad_writes = 0;
    tim_start(a, &g_song, 0, 0, SEEK_BUDGET, &mode);
    tim_start(b, &g_song, 0, 0, SEEK_BUDGET, &mode);
    tim_mute(b, 0, 1);
    tim_set_trace(b, collect, &g_col);
    for (int t = 0; t < TIA_REF_TICKS; ++t) {
        if (t == TIA_REF_TICKS / 3) tim_mute(b, 1, 1);
        tim_tick(a, g_out);
        traced_tick(b);
        if (!same_tick(&g_col, &REF_SONG, t)) ++bad_writes;
        if (!same_state(a, b)) ++bad_states;
    }
    tim_set_trace(b, NULL, NULL);
    EXPECT(bad_states == 0, "muted channels: both channels' counter states = unmuted play every tick (%d differ)", bad_states);
    EXPECT(bad_writes == 0, "muted channels: the player's writes = reference (%d ticks differ)", bad_writes);
    float* buf;
    int frames = render(b, 60, &buf);
    EXPECT(rms(buf + 2 * (RATE / 5), frames - RATE / 5) < 1e-4, "both muted: rms %.6f after 200 ms (assumption: < 1e-4)",
           rms(buf + 2 * (RATE / 5), frames - RATE / 5));
    free(buf);
    /* Unmute continuity: the probe (unmuted levels) never differed, and the mix equals unmuted play's from the first
     * tick after the unmute. */
    for (int t = 0; t < 60; ++t) tim_tick(a, g_out);
    clear_levels(&g_lv);
    clear_levels(&g_lv2);
    tim_set_level_probe(a, probe, &g_lv);
    tim_set_level_probe(b, probe, &g_lv2);
    tim_mute(b, 0, 0);
    tim_mute(b, 1, 0);
    tim_tick(a, g_out);
    tim_tick(b, g_out);
    EXPECT(g_lv.hash == g_lv2.hash && tim_level(a) == tim_level(b), "unmuted: levels identical at once (mix %d / %d)", tim_level(a),
           tim_level(b));
    int same_level = 1;
    for (int t = 0; t < 120; ++t) {
        tim_tick(a, g_out);
        tim_tick(b, g_out);
        if (tim_level(a) != tim_level(b)) same_level = 0;
    }
    EXPECT(same_level && g_lv.hash == g_lv2.hash, "unmuted: the mix follows the channels as unmuted play does");
    tim_set_level_probe(a, NULL, NULL);
    tim_set_level_probe(b, NULL, NULL);
    /* A muted channel with the other one silent: exact silence (an audition sounds on one channel only). */
    tim_audition(b, &g_tone[NTSC], 0, A4, T_DIV6, 0);
    tim_mute(b, 0, 1);
    frames = render(b, 60, &buf);
    EXPECT(frames > 0 && peak(buf, frames) == 0.0, "the only sounding channel muted: silent (peak %.6f)", peak(buf, frames));
    free(buf);
    tim_audition(b, &g_tone[NTSC], 0, A4, T_DIV6, 0);
    frames = render(b, 60, &buf);
    EXPECT(rms(buf, frames) > 0.01, "audition clears mutes (rms %.4f)", rms(buf, frames));
    free(buf);
    tim_start(b, &g_song, 0, 0, SEEK_BUDGET, &mode);
    tim_mute(b, 0, 1);
    tim_mute(b, 1, 1);
    tim_start(b, &g_song, 0, 0, SEEK_BUDGET, &mode);
    frames = render(b, 600, &buf);
    EXPECT(rms(buf, frames) > 0.005, "start clears mutes (rms %.4f)", rms(buf, frames));
    free(buf);
    EXPECT(tim_mute(b, 2, 1) == TIM_ERR_IMAGE && tim_mute(b, -1, 1) == TIM_ERR_IMAGE, "channels 2 and -1 rejected");
    tim_destroy(a);
    tim_destroy(b);
}

/* Plays `image` from the start, applying `alt0`/`alt1` (odd/even ticks) before tick t (from tick `from`; every tick or
 * only then), and compares with `ref`. */
static int play_applying(const TiaImage* image, const TiaImage* alt0, const TiaImage* alt1, int from, int every, const Ref* ref,
                         int* first) {
    TiaMachine* m = tim_create(RATE, ref->region);
    int mode, bad = 0;
    tim_start(m, image, 0, 0, SEEK_BUDGET, &mode);
    tim_set_trace(m, collect, &g_col);
    *first = -1;
    for (int t = 0; t < TIA_REF_TICKS; ++t) {
        if (t >= from && (every || t == from)) tim_apply_image(m, (t % 2) ? alt0 : alt1);
        if (!pos_is(m, ref, t)) ++bad;
        traced_tick(m);
        if (!same_tick(&g_col, ref, t)) {
            if (*first < 0) *first = t;
            ++bad;
        }
    }
    tim_destroy(m);
    return bad;
}

/* Whether the collected batch writes `reg` (value into *val), and how many writes touch channel c's registers. */
static int batch_has(int reg, int* val) {
    for (int i = 0; i < g_col.nw; ++i)
        if (g_col.w[i].reg == reg) {
            if (val) *val = g_col.w[i].val;
            return 1;
        }
    return 0;
}

static int channel_writes(int c) {
    int n = 0;
    for (int i = 0; i < g_col.nw; ++i) {
        const int reg = g_col.w[i].reg;
        if (reg == TI_REG_AUDC0 + c || reg == TI_REG_AUDF0 + c || reg == TI_REG_AUDV0 + c) ++n;
    }
    return n;
}

static void test_live_edits(void) {
    printf("live edits\n");
    int first;
    int bad = play_applying(&g_song, &g_song, &g_song, 0, 1, &REF_SONG, &first);
    EXPECT(bad == 0, "same image applied before every tick: = reference (%d differ, first %d)", bad, first);
    bad = play_applying(&g_song, &g_moved, &g_song, 0, 1, &REF_SONG, &first);
    EXPECT(bad == 0, "re-laid-out image and the original alternately before every tick: = reference (%d differ, first %d)", bad,
           first);
    bad = play_applying(&g_song, &g_pal, &g_pal, 0, 1, &REF_SONG, &first);
    EXPECT(bad == 0, "an image of the other region applied before every tick: ignored (%d differ, first %d)", bad, first);
    bad = play_applying(&g_song, &g_edited, &g_edited, TIA_REF_LIVE_AT, 0, &REF_LIVE, &first);
    EXPECT(bad == 0, "edited image applied before tick %d: = the reference's live trace (%d differ, first %d)", TIA_REF_LIVE_AT, bad,
           first);
    bad = play_applying(&g_song, &g_edited, &g_edited, 0, 0, &REF_EDITED, &first);
    EXPECT(bad == 0, "edited image applied before the first tick: = edited straight play (%d differ, first %d)", bad, first);
    bad = play_applying(&g_song, &g_tempo, &g_tempo, 0, 0, &REF_TEMPO, &first);
    EXPECT(bad == 0, "tempo image applied before the first tick: = tempo straight play (%d differ, first %d)", bad, first);
    {
        /* Cut song: positions stay inside the new song while it plays on. */
        TiaMachine* m = tim_create(RATE, NTSC);
        int mode, o, r, t, inside = 1;
        tim_start(m, &g_song, g_song.info.orders - 1, 0, SEEK_BUDGET, &mode);
        tim_tick(m, g_out);
        tim_apply_image(m, &g_short);
        for (int k = 0; k < 2000; ++k) {
            tim_position(m, &o, &r, &t);
            if (o < 0 || o >= g_short.info.orders || r < 0 || r >= g_short.info.rows[o]) inside = 0;
            tim_tick(m, g_out);
        }
        EXPECT(inside, "cut song applied in its last order: every position inside the new song for 2000 ticks");
        tim_destroy(m);
    }
    {
        /* Slot identity: byte-identical instruments in slots 1 and 2 stay separate. */
        TiaMachine* m = tim_create(RATE, NTSC);
        const TiPlayer* p = tim_player(m);
        int mode, v = -1;
        tim_start(m, &g_slots[0], 0, 0, SEEK_BUDGET, &mode);
        for (int k = 0; k < 3; ++k) tim_tick(m, g_out);
        tim_set_trace(m, collect, &g_col);
        tim_apply_image(m, &g_slots[1]);
        traced_tick(m);
        EXPECT(batch_has(TI_REG_AUDC1, &v) && v == 4 && channel_writes(0) == 0 && p->ch[0].audc == 12 && p->ch[1].audc == 4,
               "slot 2 edited: only TIA 2 changes (AUDC1 = %d, %d TIA 1 writes)", v, channel_writes(0));
        tim_apply_image(m, &g_slots[0]);
        traced_tick(m);
        EXPECT(batch_has(TI_REG_AUDC1, &v) && v == 12 && channel_writes(0) == 0, "undo: TIA 2 back to AUDC C");
        tim_apply_image(m, &g_slots[2]);
        traced_tick(m);
        EXPECT(batch_has(TI_REG_AUDV1, &v) && v == 0 && !p->ch[1].sounding && p->ch[0].sounding && channel_writes(0) == 0,
               "slot 2 removed: TIA 2's note stops (AUDV1 = 0) at its next update, TIA 1 untouched");
        tim_set_trace(m, NULL, NULL);
        tim_destroy(m);
    }
}

static void test_audition(void) {
    printf("audition\n");
    TiaMachine* m = tim_create(RATE, NTSC);
    const TiPlayer* p = tim_player(m);
    EXPECT(tim_audition(m, &g_tone[NTSC], 0, A4, T_RELEASE, 0) == TIM_OK, "A-4 with a release point");
    float* buf;
    const int frames = render(m, 60, &buf);
    EXPECT(rms(buf + 2 * (frames - RATE / 4), RATE / 4) > 0.01, "held (rms %.4f)", rms(buf + 2 * (frames - RATE / 4), RATE / 4));
    EXPECT(p->ch[0].sounding && !p->ch[1].sounding, "only TIA 1 sounds");
    free(buf);
    EXPECT(tim_release(m) == 1, "release: 1 (release phase)");
    EXPECT(tim_release(m) == 1, "a second release while releasing: still 1");
    int ticks = 0, n;
    while ((n = tim_tick(m, g_out)) > 0 && ticks < 1000) ++ticks;
    EXPECT(n == 0 && ticks >= 1 && ticks <= 10, "ends when the written AUDV reaches 0 at the envelope's end (%d ticks)", ticks);
    EXPECT(tim_tick(m, g_out) == 0 && tim_release(m) == 0, "stays ended");
    EXPECT(tim_audition(m, &g_tone[NTSC], 0, A4, T_DIV6, 0) == TIM_OK, "A-4 without envelopes");
    tim_tick(m, g_out);
    EXPECT(tim_release(m) == 0 && p->ch[0].audv == 0 && !p->ch[0].sounding && tim_tick(m, g_out) == 0,
           "release without a release point: 0, AUDV 0, tick 0");
    EXPECT(tim_audition(m, &g_tone[NTSC], 0, A4, T_DIV6, 0) == TIM_OK && tim_release(m) == 0 && tim_tick(m, g_out) == 0,
           "release before any tick: 0, then tick 0");
    for (int region = 0; region < TI_REGIONS; ++region) {
        TiaMachine* c = tim_create(RATE, region);
        tim_audition(c, &g_tone[region], 1, A4, T_CAP, 0);
        tim_tick(c, g_out);
        EXPECT(tim_release(c) == 1, "%s: release of a note whose release never reaches 0", region ? "PAL" : "NTSC");
        ticks = 0;
        while (tim_tick(c, g_out) > 0 && ticks < 2000) ++ticks;
        const double want = TIM_RELEASE_SECONDS * ticks_per_second(region);
        EXPECT(ticks >= (int)floor(want) && ticks <= (int)ceil(want) + 1, "%s: ends after %d ticks (10 s = %.1f ticks)",
               region ? "PAL" : "NTSC", ticks, want);
        tim_destroy(c);
    }
    /* apply_image during an audition is ignored */
    tim_audition(m, &g_tone[NTSC], 0, A4, T_DIV6, 0);
    tim_tick(m, g_out);
    tim_apply_image(m, &g_song);
    tim_tick(m, g_out);
    EXPECT(p->audition && p->ch[0].sounding && p->ch[0].audc == 12, "apply_image during an audition: ignored");
    /* arguments */
    EXPECT(tim_audition(m, &g_tone[NTSC], 0, A4, T_UNDEFINED, 0) == TIM_ERR_IMAGE, "undefined slot rejected");
    EXPECT(tim_audition(m, &g_tone[NTSC], 0, A4, 0, 0) == TIM_ERR_IMAGE, "slot 0 rejected");
    EXPECT(tim_audition(m, &g_tone[NTSC], 0, A4, 65, 0) == TIM_ERR_IMAGE, "slot 65 rejected");
    EXPECT(tim_audition(m, &g_tone[NTSC], 0, TI_NOTE_MAX + 1, T_DIV6, 0) == TIM_ERR_IMAGE, "note 120 rejected");
    EXPECT(tim_audition(m, &g_tone[NTSC], 0, -1, T_DIV6, 0) == TIM_ERR_IMAGE, "note -1 rejected");
    EXPECT(tim_audition(m, &g_tone[NTSC], 0, TI_NOTE_MIN, T_DIV6, 0) == TIM_OK &&
               tim_audition(m, &g_tone[NTSC], 0, TI_NOTE_MAX, T_DIV6, 0) == TIM_OK,
           "notes 0 and 119 accepted");
    EXPECT(tim_audition(m, &g_tone[NTSC], 2, A4, T_DIV6, 0) == TIM_ERR_IMAGE &&
               tim_audition(m, &g_tone[NTSC], -1, A4, T_DIV6, 0) == TIM_ERR_IMAGE,
           "channels 2 and -1 rejected");
    EXPECT(tim_audition(m, &g_tone[NTSC], 0, A4, T_DIV6, 128) == TIM_ERR_IMAGE &&
               tim_audition(m, &g_tone[NTSC], 0, A4, T_DIV6, -129) == TIM_ERR_IMAGE,
           "fine 128 and -129 rejected");
    EXPECT(tim_audition(m, &g_tone[NTSC], 0, A4, T_DIV6, 127) == TIM_OK && tim_audition(m, &g_tone[NTSC], 0, A4, T_DIV6, -128) == TIM_OK,
           "fine 127 and -128 accepted");
    EXPECT(tim_audition(m, &g_tone[PAL], 0, A4, T_DIV6, 0) == TIM_ERR_IMAGE, "a PAL image on the NTSC machine rejected");
    tim_destroy(m);
}

static void test_ops(void) {
    printf("ops tables\n");
    static const char* const ids[2] = {"atari2600-tia-ntsc", "atari2600-tia-pal"};
    for (int region = 0; region < TI_REGIONS; ++region) {
        const ChipEngineOps* ops = chip_engine_ops(ids[region]);
        EXPECT(ops && !strcmp(ops->system_id, ids[region]), "registry: %s", ids[region]);
        if (!ops) continue;
        const TiaImage* song = region == PAL ? &g_pal : &g_song;
        const TiaImage* other = region == PAL ? &g_song : &g_pal;
        EXPECT(ops->image_size == TI_IMAGE_SIZE && ops->image_storage == sizeof(TiaImage), "%s: sizes", ids[region]);
        EXPECT(ops->create(CHIP_MAX_SAMPLE_RATE + 1) == NULL, "%s: rate above the maximum rejected", ids[region]);
        ChipImage* image = (ChipImage*)calloc(1, ops->image_storage);
        ChipImage* tone = (ChipImage*)calloc(1, ops->image_storage);
        EXPECT(ops->load_image(image, song->bytes, ops->image_size - 1) == CHIP_ERR_IMAGE, "%s: wrong size rejected", ids[region]);
        EXPECT(ops->load_image(image, other->bytes, ops->image_size) == CHIP_ERR_IMAGE &&
                   ((const TiaImage*)image)->info.problem_offset == TI_H_REGION,
               "%s: an image of the other region rejected at byte 5", ids[region]);
        EXPECT(ops->load_image(image, song->bytes, ops->image_size) == CHIP_OK, "%s: song loads", ids[region]);
        EXPECT(ops->load_image(tone, g_tone[region].bytes, ops->image_size) == CHIP_OK, "%s: tone image loads", ids[region]);
        ChipMachine* m = ops->create(RATE);
        int mode = -1, o, r, t;
        EXPECT(ops->start(m, image, 0, 0, SEEK_BUDGET, &mode) == CHIP_OK && mode == CHIP_SEEK_FROM_START, "%s: start", ids[region]);
        ops->position(m, &o, &r, &t);
        EXPECT(o == 0 && r == 0 && t == 0, "%s: position 0/0/0", ids[region]);
        static float out[CHIP_MAX_TICK_FRAMES * 2];
        int frames = 0;
        const int ticks = (int)lround(ticks_per_second(region));
        for (int j = 0; j < ticks; ++j) frames += ops->tick(m, out);
        const double exact = ticks * RATE / ticks_per_second(region);
        EXPECT(fabs(frames - exact) <= 1.0, "%s: %d ticks = %d frames (exact %.1f)", ids[region], ticks, frames, exact);
        ops->apply_image(m, image);
        EXPECT(ops->mute(m, 0, 1) == CHIP_OK && ops->mute(m, 0, 0) == CHIP_OK && ops->mute(m, 2, 1) == CHIP_ERR_IMAGE, "%s: mute",
               ids[region]);
        EXPECT(ops->audition(m, tone, 0, A4, T_RELEASE, 0) == CHIP_OK, "%s: audition", ids[region]);
        ops->tick(m, out);
        EXPECT(ops->release(m) == 1, "%s: release phase", ids[region]);
        int n = 0;
        while (ops->tick(m, out) > 0 && n < 1000) ++n;
        EXPECT(n < 1000, "%s: released note ends (%d ticks)", ids[region], n);
        ops->destroy(m);
        free(image);
        free(tone);
    }
}

/* The app's exported samples, if present: each loads through its ops and plays 600 ticks with sound. */
static void test_samples(const char* samples) {
    printf("exported samples\n");
    static const struct {
        const char* file;
        const char* id;
    } files[] = {{"tia-demo.tiaimg", "atari2600-tia-ntsc"},
                 {"tia-pal-demo.tiaimg", "atari2600-tia-pal"},
                 {"tia-shortest.tiaimg", "atari2600-tia-ntsc"}};
    if (!samples) {
        printf("  skipped: no samples directory (argv[2] or THOR_SAMPLES)\n");
        return;
    }
    for (size_t i = 0; i < sizeof files / sizeof files[0]; ++i) {
        char path[512];
        snprintf(path, sizeof path, "%s/%s", samples, files[i].file);
        FILE* f = fopen(path, "rb");
        if (!f) {
            printf("  skipped: %s not found (run `tools/build.sh exportSamples`)\n", path);
            continue;
        }
        static uint8_t bytes[TI_IMAGE_SIZE + 1];
        const size_t size = fread(bytes, 1, sizeof bytes, f);
        fclose(f);
        const ChipEngineOps* ops = chip_engine_ops(files[i].id);
        ChipImage* image = (ChipImage*)calloc(1, sizeof(TiaImage));
        const int rc = ops ? ops->load_image(image, bytes, size) : CHIP_ERR_IMAGE;
        EXPECT(rc == CHIP_OK, "%s loads through %s (%s at %d)", files[i].file, files[i].id,
               rc ? (((const TiaImage*)image)->info.problem ? ((const TiaImage*)image)->info.problem : "size") : "ok",
               ((const TiaImage*)image)->info.problem_offset);
        if (rc == CHIP_OK) {
            ChipMachine* m = ops->create(RATE);
            int mode, ok = 1;
            double p = 0;
            ok = ops->start(m, image, 0, 0, SEEK_BUDGET, &mode) == CHIP_OK;
            static float out[CHIP_MAX_TICK_FRAMES * 2];
            for (int t = 0; ok && t < 600; ++t) {
                const int n = ops->tick(m, out);
                if (n <= 0) ok = 0;
                for (int j = 0; j < 2 * n; ++j)
                    if (fabs(out[j]) > p) p = fabs(out[j]);
            }
            EXPECT(ok && p > 0, "%s: 600 ticks without error, peak %.4f", files[i].file, p);
            ops->destroy(m);
        }
        free(image);
    }
}

static void test_costs(void) {
    printf("costs\n");
    TiaMachine* m = tim_create(RATE, NTSC);
    int mode;
    double t0 = now_us();
    tim_start(m, &g_song, g_song.info.orders - 1, 0, SEEK_BUDGET, &mode);
    const double seek = now_us() - t0;
    t0 = now_us();
    for (int k = 0; k < 600; ++k) tim_tick(m, g_out);
    const double per = (now_us() - t0) / 600;
    TiPlayer* p = (TiPlayer*)malloc(sizeof *p);
    t0 = now_us();
    tip_reset(p, &g_song);
    for (int k = 0; k < TIM_SEEK_TICKS; ++k) tip_tick(p, &g_song);
    const double player = (now_us() - t0) / TIM_SEEK_TICKS;
    free(p);
    printf("  seek to order %d: %.0f us; %.1f us per clocked tick; player alone %.2f us per tick\n", g_song.info.orders - 1, seek,
           per, player);
    tim_destroy(m);
}

int main(int argc, char** argv) {
    const char* dir = argc > 1 ? argv[1] : ".";
    const char* samples = argc > 2 ? argv[2] : getenv("THOR_SAMPLES");
    EXPECT(load(&g_song, tia_song_image, sizeof tia_song_image, NTSC) == 0, "song loads: %s", g_song.info.problem);
    EXPECT(load(&g_moved, tia_moved_image, sizeof tia_moved_image, NTSC) == 0, "moved loads: %s", g_moved.info.problem);
    EXPECT(load(&g_edited, tia_edited_image, sizeof tia_edited_image, NTSC) == 0, "edited loads: %s", g_edited.info.problem);
    EXPECT(load(&g_tempo, tia_tempo_image, sizeof tia_tempo_image, NTSC) == 0, "tempo loads: %s", g_tempo.info.problem);
    EXPECT(load(&g_short, tia_short_image, sizeof tia_short_image, NTSC) == 0, "short loads: %s", g_short.info.problem);
    EXPECT(load(&g_pal, tia_pal_image, sizeof tia_pal_image, PAL) == 0, "PAL loads: %s", g_pal.info.problem);
    build_tone(&g_tone[NTSC], NTSC);
    build_tone(&g_tone[PAL], PAL);
    build_slots();
    build_unreachable();
    test_tables();
    test_images();
    test_reference(dir);
    test_levels();
    test_frames();
    test_audio(dir);
    test_pitch(dir);
    test_seek();
    test_mute();
    test_headroom();
    test_live_edits();
    test_audition();
    test_ops();
    test_samples(samples);
    test_costs();
    printf("Atari 2600 (TIA): %d checks, %d failures\n", checks, failures);
    return failures ? 1 : 0;
}
